COMMENT ON COLUMN CHARACTERS.MOVIE_TITLE IS 'unique title of the movie';
COMMENT ON COLUMN CHARACTERS.RELEASE_DATE IS 'The release date of the movie.';
COMMENT ON COLUMN CHARACTERS.HERO IS 'The main character of the movie.';
ALTER TABLE CHARACTERS MODIFY (HERO ANNOTATIONS (ADD value_description 'commonsense evidence:round role'));
COMMENT ON COLUMN CHARACTERS.VILLIAN IS 'The villain of the movie.';
ALTER TABLE CHARACTERS MODIFY (VILLIAN ANNOTATIONS (ADD value_description 'a character whose evil actions or motives are important to the plot.'));
COMMENT ON COLUMN CHARACTERS.SONG IS 'A song associated with the movie.';
COMMENT ON COLUMN DIRECTOR."NAME" IS 'unique movie name';
COMMENT ON COLUMN DIRECTOR.DIRECTOR IS 'the name of the director';
ALTER TABLE DIRECTOR MODIFY (DIRECTOR ANNOTATIONS (ADD value_description 'one director may have multiple movies.more movies --> this director is more productive'));
COMMENT ON COLUMN MOVIES_TOTAL_GROSS.MOVIE_TITLE IS 'movie title';
COMMENT ON COLUMN MOVIES_TOTAL_GROSS.RELEASE_DATE IS 'release date';
COMMENT ON COLUMN MOVIES_TOTAL_GROSS.GENRE IS 'genre of the movie';
COMMENT ON COLUMN MOVIES_TOTAL_GROSS.MPAA_RATING IS 'Motion Picture Association of America of the disney movie';
ALTER TABLE MOVIES_TOTAL_GROSS MODIFY (MPAA_RATING ANNOTATIONS (ADD value_description 'commonsense evidence:â¢ G: general audienceâ¢ PG: mature audiences or parental guidance suggestedâ¢ R: restricted: no children under 17 allowed without parents or adult guardiansâ¢ PG-13: PARENTS STRONGLY CAUTIONED. Some material may be inappropriate for children under 13movies need accompany with parents: PG, PG-13, PG-17;if "Not rated" or null, it means this film can show only gets permissions by theatre managementif the film can show without need of permissions of theatre management, the MPAA_rating should not be "Not rated" or null'));
COMMENT ON COLUMN MOVIES_TOTAL_GROSS.TOTAL_GROSS IS 'The total gross of the movie.';
ALTER TABLE MOVIES_TOTAL_GROSS MODIFY (TOTAL_GROSS ANNOTATIONS (ADD value_description 'commonsense evidence:more total_gross--> more popular movie'));
COMMENT ON COLUMN MOVIES_TOTAL_GROSS.INFLATION_ADJUSTED_GROSS IS 'The inflation-adjusted gross of the movie.';
ALTER TABLE MOVIES_TOTAL_GROSS MODIFY (INFLATION_ADJUSTED_GROSS ANNOTATIONS (ADD value_description 'commonsense evidence:estimated inflation rate = inflation_adjusted_gross / total_gross;the current gross = inflation_adjusted_gross'));
COMMENT ON COLUMN REVENUE."YEAR" IS 'The year the movie was released.';
COMMENT ON COLUMN REVENUE."STUDIO ENTERTAINMENT[NI 1]" IS 'The studio entertainment segment of the Walt Disney Company.';
COMMENT ON COLUMN REVENUE."DISNEY CONSUMER PRODUCTS[NI 2]" IS 'The consumer products segment of the Walt Disney Company.';
COMMENT ON COLUMN REVENUE."DISNEY INTERACTIVE[NI 3][REV 1]" IS 'The interactive segment of the Walt Disney Company.';
COMMENT ON COLUMN REVENUE."WALT DISNEY PARKS AND RESORTS" IS 'The parks and resorts segment of the Walt Disney Company.';
COMMENT ON COLUMN REVENUE."DISNEY MEDIA NETWORKS" IS 'The media networks segment of the Walt Disney Company.';
COMMENT ON COLUMN REVENUE.TOTAL IS 'The total box office gross for the movie.';
COMMENT ON COLUMN "VOICE_ACTORS"."CHARACTER" IS 'The unique name of the character.';
COMMENT ON COLUMN "VOICE_ACTORS"."VOICE_ACTOR" IS 'The name of the voice actor.';
COMMENT ON COLUMN "VOICE_ACTORS".MOVIE IS 'The name of the movie.';